// 自动生成的请求头预览（Headers 页底部灰色只读区，参照 Postman 的 auto-generated headers）。
// 规则复刻 Go 侧 http_service.go 的运行时行为；"用户是否已设"一律以 buildGoRequest 产物
// （祖先公共头 + 自身头 + auth 注入合并后的最终头集）判定，已设则不再重复展示。
import { buildGoRequest } from './send'
import type { Request } from '../types/models'
import { APP_VERSION } from '../types/models'

export interface AutoHeader {
  key: string
  value: string
}

type GoRequest = ReturnType<typeof buildGoRequest>

/** 与 Go url.QueryEscape 完全一致：unreserved（A-Z a-z 0-9 - _ . ~）不转义，空格→+，其余 %XX 大写 */
export function queryEscapeGo(s: string): string {
  const bytes = new TextEncoder().encode(s)
  let out = ''
  for (const b of bytes) {
    if (
      (b >= 0x41 && b <= 0x5a) ||
      (b >= 0x61 && b <= 0x7a) ||
      (b >= 0x30 && b <= 0x39) ||
      b === 0x2d || // -
      b === 0x5f || // _
      b === 0x2e || // .
      b === 0x7e // ~
    ) {
      out += String.fromCharCode(b)
    } else if (b === 0x20) {
      out += '+'
    } else {
      out += '%' + b.toString(16).toUpperCase().padStart(2, '0')
    }
  }
  return out
}

/** 从（可能缺 scheme 的）URL 提取 Host 值（host:port，port 缺省则省略） */
function hostOf(url: string): string {
  const u = url.trim()
  if (!u) return ''
  for (const candidate of [u, 'http://' + u]) {
    try {
      const p = new URL(candidate)
      return p.port ? `${p.hostname}:${p.port}` : p.hostname
    } catch {
      // 继续试补 scheme
    }
  }
  return ''
}

/** 复刻 Go buildBody 的 Content-Type hint 规则（含空 body 不出的分支） */
function contentTypeHint(go: GoRequest): string {
  switch (go.bodyType) {
    case 'raw':
      if (!go.body) return ''
      switch (go.rawLang) {
        case 'json':
          return 'application/json'
        case 'xml':
          return 'application/xml'
        case 'html':
          return 'text/html'
        default:
          return 'text/plain'
      }
    case 'urlencoded':
      return go.urlEncoded.some((u) => u.key) ? 'application/x-www-form-urlencoded' : ''
    case 'form-data':
      return go.formData.some((f) => f.enabled && f.key) ? 'multipart/form-data' : ''
    case 'binary':
      return go.binaryPath ? 'application/octet-stream' : ''
    case 'graphql':
      return go.graphql ? 'application/json' : ''
    default:
      return ''
  }
}

/** Content-Length 仅 raw / urlencoded 可精确预知；form-data（multipart boundary 运行时生成）、
 *  binary（文件在 Go 侧打开）、graphql（JSON marshal 形态不同）一律不出，避免误导 */
function contentLength(go: GoRequest): number | null {
  if (go.bodyType === 'raw' && go.body) {
    return new TextEncoder().encode(go.body).length
  }
  if (go.bodyType === 'urlencoded') {
    const s = go.urlEncoded
      .filter((u) => u.key)
      .map((u) => queryEscapeGo(u.key) + '=' + queryEscapeGo(u.value))
      .join('&')
    return new TextEncoder().encode(s).length
  }
  return null
}

export function autoGeneratedHeaders(request: Request): AutoHeader[] {
  const go = buildGoRequest(request, { resolve: true })
  const userSet = new Set(go.headers.filter((h) => h.enabled).map((h) => h.key.trim().toLowerCase()))
  const out: AutoHeader[] = []
  const host = hostOf(go.url)
  if (host) out.push({ key: 'Host', value: host })
  const ct = contentTypeHint(go)
  if (ct && !userSet.has('content-type')) out.push({ key: 'Content-Type', value: ct })
  const cl = contentLength(go)
  if (cl !== null) out.push({ key: 'Content-Length', value: String(cl) })
  // Go transport 行为：未显式设置时自动加 gzip
  if (!userSet.has('accept-encoding')) out.push({ key: 'Accept-Encoding', value: 'gzip' })
  // Go 侧 applyHeaders 的 UA 兜底（与 defaultUserAgent 常量交叉锁定）
  if (!userSet.has('user-agent')) out.push({ key: 'User-Agent', value: `Voltra/${APP_VERSION}` })
  return out
}
